CREATE TABLE IF NOT EXISTS species (
  id INTEGER PRIMARY KEY,           
  master_id INTEGER,
  scientific TEXT,
  common TEXT,
  aliases TEXT,                     
  family TEXT,
  growth_form TEXT,
  native_distribution TEXT,
  conservation_status TEXT,
  native INTEGER,                   
  ffw_url TEXT,
  tree_count INTEGER,
  family_src TEXT,                  
  native_src TEXT,                  
  wood_density REAL,                
  wood_density_src TEXT             
);

CREATE TABLE IF NOT EXISTS places (
  id INTEGER PRIMARY KEY,
  kind TEXT NOT NULL,               
  slug TEXT NOT NULL,
  name TEXT NOT NULL,
  alt TEXT,                         
  tree_count INTEGER,
  species_count INTEGER,
  heritage_count INTEGER,
  carbon_kg REAL,
  bbox TEXT,                        
  top_species TEXT,                 
  extra TEXT                        
);

CREATE TABLE IF NOT EXISTS trees (
  id INTEGER PRIMARY KEY,           
  lng REAL NOT NULL,
  lat REAL NOT NULL,
  cell INTEGER NOT NULL,            
  species_id INTEGER,
  girth_m REAL,
  girth_band TEXT,
  size TEXT,
  height_band TEXT,
  height_m INTEGER,                 
  age INTEGER,
  category TEXT,                    
  date_planted TEXT,
  incorrect INTEGER,
  road_id INTEGER,
  road_dist REAL,
  subzone_id INTEGER,
  pa_id INTEGER,
  park_id INTEGER,
  pcn_id INTEGER,
  ed_id INTEGER,
  hr_id INTEGER,
  tca TEXT,
  nature_way TEXT,
  land_use TEXT,
  ht_no TEXT,
  ht_url TEXT,
  ht_desc TEXT,
  carbon_kg REAL,                   
  carbon_nparks REAL,               
  last_edited TEXT,
  measure_flag INTEGER,             
  carbon_skip TEXT                  
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_places_kind_slug ON places(kind, slug);




CREATE INDEX IF NOT EXISTS idx_trees_road ON trees(road_id) WHERE road_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_trees_park ON trees(park_id) WHERE park_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_trees_subzone ON trees(subzone_id);
CREATE INDEX IF NOT EXISTS idx_trees_pa ON trees(pa_id);
CREATE INDEX IF NOT EXISTS idx_trees_pcn ON trees(pcn_id) WHERE pcn_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_trees_ed ON trees(ed_id);
CREATE INDEX IF NOT EXISTS idx_trees_hr ON trees(hr_id) WHERE hr_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_trees_species ON trees(species_id);
CREATE INDEX IF NOT EXISTS idx_trees_cell ON trees(cell);


CREATE TABLE IF NOT EXISTS top_trees (
  rank INTEGER PRIMARY KEY,
  tree_id INTEGER NOT NULL
);


CREATE TABLE IF NOT EXISTS changes (
  tree_id INTEGER NOT NULL,
  change TEXT NOT NULL,             
  seen TEXT NOT NULL,               
  since TEXT,                       
  lng REAL,
  lat REAL,
  common TEXT,
  scientific TEXT,
  girth_m REAL,
  road_id INTEGER,
  park_id INTEGER,
  subzone_id INTEGER,
  pa_id INTEGER,
  ed_id INTEGER,
  PRIMARY KEY (tree_id, change, seen)
);

CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT);

